"""Rule 8 of .github/scripts/check-workflow-files.sh: in ci.yaml's run, every step that runs go
test keeps its events through .github/scripts/go_test_events.py, under an id of its own, and its
job uploads them after it with .github/actions/go-test-events-upload. The check's header says
what the rule refuses and why; this module is how it reads a step, through the shell reader beside
it (.github/scripts/go_test_shell.py).

The check imports this module from beside its own file and calls check_go_test_events for each
workflow file of that run with its own `problem` and one cache of script reads for the whole run,
so each fault is reported in its file's order beside the check's other faults. Each call returns
the file's Census: the commands, steps and jobs it holds to the rule, and every script its steps
reached, with the first step that reached it. The check sums them (total) for its last line and
hands the scripts to hold_scripts_to_filter once, after every file. The module keeps no state of
its own, so no result depends on the order the steps are read in. Its cases are
.github/scripts/go_test_steps.test.sh, and the shell forms it is held to are generated by
.github/scripts/go_test_step_forms.py, whose known misses .github/go-test-step-misses.tsv lists.
"""

from __future__ import annotations

import ast
import os
import re
from enum import Enum
from pathlib import Path
from typing import Callable, NamedTuple

import yaml
from go_test_events import ENV_FILE, TRUE, GoArgs
from go_test_shell import (ASSIGNS, POOL_WAIT, RUNS, TEES, commands, detached_at, flag_words, go_test_parts,
                           go_tests, logical_lines, runs_script, unquoted)
from workflow_paths import EVENTS_WRITER, PathsFilter, mapping_get, scalar

Problem = Callable[..., None]

WRITER = EVENTS_WRITER
# The harnesses whose own go test runs are fixtures: the runs each of their cases compares or
# plants, over a module or a narrowed package of the harness's making, and no test of this
# repository a reader asks the result of. A step that runs one is no go test step, and its other
# go test commands are held as any step's are. Each entry says why.
FIXTURES = {
    ".github/scripts/go_test_events.test.sh":
        "the writer's own harness: its plain go test runs over a scratch module are what each case "
        "compares the writer's log with",
    "packages/envoy/scripts/database-skips.test.sh":
        "the skip counter's controls: each runs the counter over a planted or narrowed package to "
        "hold its count, and envoy-go's database-skips step is the counter's own run",
    "packages/envoy/scripts/forced-order.test.sh":
        "forced-order.sh's refusals: its one run that reaches a test run is over the fixture package "
        "hooktest/skiponly, whose one test skips, and keeps that fixture's events in the harness's own "
        "directory; the forced-order steps are the script's own runs",
    ".github/scripts/go-legs.test.sh":
        "go_legs.py's harness: its verbose go test runs are over a module of its own making in a "
        "scratch tree, which each case reads to say which tests a leg's printed arguments ran",
    "packages/envoy/scripts/airlock-mutants.test.sh":
        "airlock-mutants.sh's count harness: it runs a copy of the script in a fixture tree of its own "
        "making with a stand-in go first on its PATH (its header and its run()), so the go test the "
        "script reaches is answered from the fixture and runs no test of this repository",
}
# The one upload a job that runs go test makes, after its last such step: the local action holds
# the artifact's name, the directory and if-no-files-found, and the job hands it its own id.
UPLOAD_ACTION = "./.github/actions/go-test-events-upload"
UPLOAD_WITH = {"check-run-id": "${{ job.check_run_id }}"}

SCRIPT_SUFFIXES = (".sh", ".py")


def known(value: str | None) -> bool:
    """Whether a flag's value is one this check can read: none the shell or Python computes when
    the step runs (a word flag_words or the Python reader gives as None)."""
    return value is not None


def runs_no_test(words: list[str | None]) -> bool:
    """Whether go test with these words runs no test, its flags read as go reads them (GoArgs,
    the events writer's own reader of cmd/go's testFlags, so the two cannot drift): -c true
    compiles only, and -list with a pattern lists the test names and runs none (an empty -list
    runs them). A word after `--`, `-args` or the end of go test's own words is the test binary's.
    A value this check cannot read is no evidence that no test runs."""
    flags = GoArgs(words).flags
    compiles, listing = flags.get("c", "false"), flags.get("list", "")
    return (known(compiles) and compiles in TRUE) or (known(listing) and listing != "")


def compile_only(rest: str) -> bool:
    """A go test whose words after `test` run no test (runs_no_test)."""
    return runs_no_test(flag_words(rest))


def writes_json(rest: str) -> bool:
    """A go test whose own flags set -json true, as go reads them: its stdout is test2json events."""
    value = GoArgs(flag_words(rest)).flags.get("json", "false")
    return known(value) and value in TRUE


def names_writer(word: str) -> bool:
    """Whether a word is the writer's repository path, or a path that ends in it."""
    return word == WRITER or word.endswith("/" + WRITER)


def resolve(word: str, places: list[Path]) -> Path | None:
    """The repository script a command word names, looked for from each of `places`: a file whose
    name ends .sh or .py, or one whose first line names a shell (`#!/usr/bin/env bash`), the writer
    aside. A word the shell builds (`$dir/x.sh`, `"$(dirname "$0")/x.sh"`) is looked for by its file
    name in the first place."""
    if "$" in word:
        candidates = [places[0] / Path(word).name]
    else:
        candidates = [place / word.removeprefix("./") for place in places] + [Path(word.removeprefix("./"))]
    for candidate in candidates:
        try:
            relative = candidate.resolve().relative_to(Path.cwd().resolve())
        except ValueError:
            continue
        if not relative.is_file() or relative == Path(WRITER):
            continue
        if relative.suffix in SCRIPT_SUFFIXES:
            return relative
        try:
            with open(relative, "rb") as opened:
                first = opened.readline(200)
        except OSError:
            continue
        if first.startswith(b"#!") and re.search(rb"\b(?:ba|da|z|k)?sh\b", first):
            return relative
    return None


class Keep(Enum):
    """How a go test a script runs keeps its events: SELF when it runs under the writer, TEES when
    its own line tees what it writes into TEST_EVENTS_FILE (kept only under a writer that sets it),
    and NONE when it keeps none. Whether its step can end first (detached_at) is apart from this:
    a go test behind `setsid -f` or `&` is bare or kept all the same, and refused as both."""
    SELF = "self"
    TEES = "tees"
    NONE = "none"


class GoTest(NamedTuple):
    """A go test command a script runs: its file, its line, the command, how it keeps its events,
    whether it runs detached, and whether the writer runs it under a go word it does not take
    (misspelled_go)."""
    file: Path
    line: int
    command: str
    keep: Keep
    detached: bool = False
    misspelled: bool = False


class Unparsable(NamedTuple):
    """A Python script Python's parser refuses, so whether it runs go test is unknown: its file,
    the line the parser names, and the parser's words."""
    file: Path
    line: int
    error: str


class ScriptRead(NamedTuple):
    """What reading a script found, through the scripts it runs: its go tests, the Python scripts
    it reaches that do not parse, every script it read (itself first), and the scripts the cycle
    guard cut its reading at, which a reader further up is reading: a read cut at any but itself is
    incomplete, and is not kept for another step to reuse."""
    tests: tuple[GoTest, ...] = ()
    unparsable: tuple[Unparsable, ...] = ()
    scripts: tuple[Path, ...] = ()
    cut: frozenset = frozenset()


# A Python script runs go test as an argv, a list or tuple whose first element is the string "go"
# (or the writer's path, then "go"; or python3 and the writer's path, then "go"), then "test", -C
# and its directory standing between them or not. It is read with Python's own parser, so a
# docstring, a comment or another command's argument that holds the words "go" and "test" is no
# run, and a comment inside the argv hides nothing. Such a list printed or formatted (anywhere
# inside an argument of DATA_CALLS, or inside an f-string) is data; any other is read as an argv,
# since a script keeps its argv in a variable as often as it passes it straight to subprocess. An
# argv that builds its "go" another way (a variable, a computed list) is not followed, and an
# element the argv computes is read as no flag of go test's, its value unknown: a computed flag
# that overrides a literal one (`"-list=" + x` after `"-list", "Test"`) is not read. A script
# Python cannot parse is refused by name, as such a script, and is no go test step.
# `" ".join(argv)` is not among them: a script hands the shell such a string to run as often as it
# prints one, and a print of it is data through print.
DATA_CALLS = frozenset({"print", "repr", "str", "format", "dumps", "debug", "info", "warning", "error",
                        "exception", "critical", "log", "write"})


# Calls that only turn their arguments into text or another container, inside a printed or
# formatted expression: what they are handed is still only printed.
FORMATTING_CALLS = frozenset({"join", "str", "repr", "format", "dumps", "list", "tuple", "sorted"})


def data_nodes(node: ast.AST) -> set[int]:
    """The ids of a printed or formatted expression's nodes that are only data: every node inside
    it but those inside a call it makes, which runs before its result is printed (a printed
    `subprocess.run([...])` runs its argv), a call of FORMATTING_CALLS aside (a printed
    `" ".join([...])` only prints)."""
    marked, pending = set(), [node]
    while pending:
        current = pending.pop()
        marked.add(id(current))
        if isinstance(current, ast.Call):
            function = current.func
            name = function.attr if isinstance(function, ast.Attribute) else getattr(function, "id", "")
            if name not in FORMATTING_CALLS:
                continue
        pending.extend(ast.iter_child_nodes(current))
    return marked


def data_lists(tree: ast.AST) -> set[int]:
    """The ids of the list and tuple literals the script only prints or formats."""
    data = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            function = node.func
            name = function.attr if isinstance(function, ast.Attribute) else getattr(function, "id", "")
            if name in DATA_CALLS:
                for argument in [*node.args, *(k.value for k in node.keywords)]:
                    data |= data_nodes(argument)
        elif isinstance(node, ast.FormattedValue):
            data |= data_nodes(node.value)
    return data


def python_argv(node: ast.AST) -> tuple[bool, list[ast.AST]] | None:
    """For a list or tuple literal that is a go test argv: whether the writer runs it, and the
    elements after "test"; None for any other node."""
    if not isinstance(node, (ast.List, ast.Tuple)):
        return None
    items = node.elts

    def text(at: int) -> str | None:
        element = items[at] if at < len(items) else None
        return element.value if isinstance(element, ast.Constant) and isinstance(element.value, str) else None

    start, writer = 0, False
    if text(0) in ("python3", "python") and names_writer(text(1) or ""):
        start, writer = 2, True
    elif names_writer(text(0) or ""):
        start, writer = 1, True
    if text(start) != "go":
        return None
    at = start + 1
    if text(at) == "-C":
        at += 2
    elif (text(at) or "").startswith("-C="):
        at += 1
    if text(at) != "test":
        return None
    return writer, items[at + 1:]


def python_tests(script: Path, text: str) -> ScriptRead:
    """The go test argvs a Python script holds, those whose flags run no test (runs_no_test) aside,
    or the script as one Python cannot parse. A flag the argv computes is unknown, so it is read as
    running tests."""
    try:
        tree = ast.parse(text, filename=str(script))
    except (SyntaxError, ValueError) as error:
        return ScriptRead(unparsable=(Unparsable(script, getattr(error, "lineno", None) or 1, str(error)),),
                          scripts=(script,))
    data = data_lists(tree)
    found = []
    for node in ast.walk(tree):
        argv = python_argv(node) if id(node) not in data else None
        if argv is None:
            continue
        writer, rest = argv
        # A computed element is None: GoArgs reads it as no flag, and as a flag's value it is one
        # runs_no_test cannot read, so it is no evidence that no test runs.
        words = [item.value if isinstance(item, ast.Constant) and isinstance(item.value, str) else None
                 for item in rest]
        if runs_no_test(words):
            continue
        found.append(GoTest(script, node.lineno, f"{ast.unparse(node)} (a Python argv)",
                            Keep.SELF if writer else Keep.NONE))
    return ScriptRead(tests=tuple(found), scripts=(script,))


def misspelled_go(match: re.Match, line: str) -> bool:
    """Whether the writer runs a go test under a go word other than `go` (`<writer> "$GO" test`,
    `<writer> /usr/local/go/bin/go test`): its first form takes the word `go` alone, and it runs any
    other word as its second form, a command that tees its own events, which go test does not, so
    the step keeps none and fails. race_memory.py between the two runs the command itself."""
    return (bool(match.group("wrapper")) and match.group("go").strip("\"'") != "go"
            and "race_memory.py" not in line[match.start("cmd"):match.start("go")])


def keeps_of(match: re.Match, line: str) -> Keep:
    if match.group("wrapper"):
        return Keep.SELF
    # A tee keeps events only of a go test that writes them: -json true among its own flags.
    _, rest, end = go_test_parts(match, line)
    if not writes_json(rest):
        return Keep.NONE
    tee = TEES.match(line[end:])
    return Keep.TEES if tee and unquoted(line)[end + tee.start()] else Keep.NONE


def run_under(reached: ScriptRead, detached: bool, writer: bool) -> tuple[GoTest, ...]:
    """The go tests a script reaches, as the command that runs the script keeps them: every one
    detached when that command is, and under the writer each one that tees its events on its own
    line kept by that writer, since it sets their file."""
    return tuple(test._replace(detached=test.detached or detached,
                               keep=Keep.SELF if writer and test.keep is Keep.TEES else test.keep)
                 for test in reached.tests)


def script_tests(script: Path, cache: dict, seen: frozenset = frozenset()) -> ScriptRead:
    """Every go test command the script runs, itself or through the scripts it runs, followed
    until nothing more joins (a script `seen` holds is being read further up, and is cut). A
    compile-only go test -c runs no test, and a fixture harness's runs are its own. A Python script
    is read for its go test argvs alone (python_tests). `cache` keeps each read that no cut left
    incomplete, so the read of a script is the same whichever step reaches it first."""
    if script in seen:
        return ScriptRead(cut=frozenset({script}))
    if str(script) in FIXTURES:
        return ScriptRead()
    if script in cache:
        return cache[script]
    try:
        text = script.read_text(errors="replace")
    except OSError:
        return ScriptRead(scripts=(script,))
    if script.suffix == ".py":
        cache[script] = python_tests(script, text)
        return cache[script]
    tests, unparsable, scripts, cut = [], [], [script], set()
    lines = logical_lines(text)
    for at, (number, line) in enumerate(lines):
        later = lines[at + 1:]
        for match in go_tests(line):
            command, rest, _ = go_test_parts(match, line)
            if not compile_only(rest):
                tests.append(GoTest(script, number, command, keeps_of(match, line), detached_at(match, line, "cmd", later),
                                    misspelled_go(match, line)))
        for match in commands(RUNS, line, "arg"):
            inner = resolve(match.group("word"), [script.parent, script.parent.parent, Path(".")])
            if inner is None or not runs_script(match):
                continue
            reached = script_tests(inner, cache, seen | {script})
            tests += run_under(reached, detached_at(match, line, "arg", later), bool(match.group("wrapper")))
            unparsable += reached.unparsable
            scripts += [path for path in reached.scripts if path not in scripts]
            cut |= reached.cut
    read = ScriptRead(tuple(tests), tuple(unparsable), tuple(scripts), frozenset(cut - {script}))
    if not read.cut:
        cache[script] = read
    return read


class StepScan(NamedTuple):
    """What one step's run: holds: the go test commands it keeps (`kept`), and what each refusal
    names: those it runs other than through the writer (`bare`), those of a script it runs under
    the writer that keep nothing (`leaky`), those that run detached, those the writer runs under a
    go word it does not take (`misspelled`), and the Python scripts it reaches that do not parse;
    whether it sets TEST_EVENTS_FILE itself, queues a go test in the harness pool, or waits for the
    pool; and every script it read."""
    kept: int
    bare: list[str]
    leaky: list[str]
    detached: list[str]
    misspelled: list[str]
    unparsable: list[str]
    assigns: bool
    pooled: bool
    pool_wait: bool
    scripts: tuple[Path, ...]


def scan_step(run: str, workdir: Path, cache: dict) -> StepScan:
    """Read one step's run: for rule 8, run from `workdir`."""
    kept, bare, leaky, detached, misspelled, unparsable, scripts = 0, [], [], [], [], [], []
    assigns = pooled = pool_wait = False
    lines = logical_lines(run)
    for at, (_, text) in enumerate(lines):
        later = lines[at + 1:]
        pool_wait = pool_wait or bool(commands(POOL_WAIT, text, "pool"))
        assigns = assigns or bool(commands(ASSIGNS, text, "name"))
        for match in go_tests(text):
            command, rest, _ = go_test_parts(match, text)
            if compile_only(rest):
                continue
            pooled = pooled or bool(match.group("pooled"))
            if detached_at(match, text, "cmd", later):
                detached.append(f"`{command}`")
            if not match.group("wrapper"):
                bare.append(f"`{command}`")
            elif misspelled_go(match, text):
                misspelled.append(f"`{command}`")
            else:
                kept += 1
        for match in commands(RUNS, text, "arg"):
            script = resolve(match.group("word"), [workdir, Path(".")])
            if script is None or str(script) in FIXTURES or not runs_script(match):
                continue
            read = script_tests(script, cache)
            scripts += [path for path in read.scripts if path not in scripts]
            unparsable += [f"{script}, {'' if file == script else f'which runs {file}, '}a Python script this check "
                           f"cannot parse ({file}:{line}: {error})" for file, line, error in read.unparsable]
            if not read.tests:
                continue
            pooled = pooled or bool(match.group("pooled"))
            writer = bool(match.group("wrapper"))
            reached = run_under(read, detached_at(match, text, "arg", later), writer)
            detached += [f"{script}, which runs `{test.command}` ({test.file}:{test.line})"
                         for test in reached if test.detached]
            misspelled += [f"{script}, which runs `{test.command}` ({test.file}:{test.line})"
                           for test in reached if test.misspelled]
            if writer:
                # The writer sets TEST_EVENTS_FILE for the script: a tee keeps its events.
                kept += 1
                leaky += [f"`{test.command}` ({test.file}:{test.line})" for test in reached if test.keep is Keep.NONE]
                continue
            unkept = [test for test in reached if test.keep is not Keep.SELF]
            if unkept:
                bare.append(f"{script}, which runs `{unkept[0].command}` ({unkept[0].file}:{unkept[0].line})")
            elif not any(test.misspelled for test in reached):
                kept += 1
    return StepScan(kept, bare, leaky, detached, misspelled, unparsable, assigns, pooled, pool_wait, tuple(scripts))


def step_env_names(*holders) -> set[str]:
    names = set()
    for holder in holders:
        env = mapping_get(holder, "env")
        if isinstance(env, yaml.MappingNode):
            names |= {scalar(name) for name, _ in env.value}
    return names


def condition(text: str) -> str:
    """An `if:` as GitHub reads it: the expression inside `${{ }}`, its blanks one."""
    text = " ".join(text.split())
    if text.startswith("${{") and text.endswith("}}"):
        text = text[3:-2].strip()
    return text


def step_if(step: object) -> str:
    """A step's `if:` as GitHub reads it, or "" when it has none."""
    return condition(scalar(mapping_get(step, "if")) or "")


def with_shared(bases: set[str], conditions: set[str]) -> set[str]:
    """The conditions `bases` name, and each of them joined to the one condition every go test step
    of the job carries, bare or parenthesized, when they all carry one."""
    out = set(bases)
    if len(conditions) == 1 and "" not in conditions:
        (only,) = conditions
        out |= {f"{base} && {only}" for base in bases} | {f"{base} && ({only})" for base in bases}
    return out


class StepAt(NamedTuple):
    """A step as a refusal names it: its file, its line, and the words that name it."""
    path: Path
    line: int
    where: str


class StepRef(NamedTuple):
    """A step of a job: its number, its name and its line."""
    index: int
    name: str
    line: int


class Census(NamedTuple):
    """What rule 8 read of one workflow file, or of several (total): the go test commands it
    keeps, the steps and jobs that run them, and every script their steps reached, each with the
    first step that reached it."""
    commands: int
    steps: int
    jobs: int
    scripts: dict


def total(censuses: list[Census]) -> Census:
    """The censuses summed, each script kept with the first step that reached it."""
    scripts: dict[Path, StepAt] = {}
    for census in censuses:
        for script, step in census.scripts.items():
            scripts.setdefault(script, step)
    return Census(sum(c.commands for c in censuses), sum(c.steps for c in censuses),
                  sum(c.jobs for c in censuses), scripts)


def check_go_test_events(path: Path, root: object, problem: Problem, cache: dict | None = None) -> Census:
    """Rule 8: each go test step keeps its events, under an id of its own, and its job uploads
    them after it. A step that runs go test other than through the writer is a go test step all
    the same: it is refused for that, and held to the id and the upload too, so one run names
    every fault of it. `cache` holds the reads of the scripts the steps run, for the whole run of
    the check; the file's Census is returned."""
    cache = {} if cache is None else cache
    jobs = mapping_get(root, "jobs")
    if not isinstance(jobs, yaml.MappingNode):
        return total([])
    workflow_dir = scalar(mapping_get(mapping_get(mapping_get(root, "defaults"), "run"), "working-directory"))
    censuses = []
    for job_name, job in jobs.value:
        steps = mapping_get(job, "steps")
        if not isinstance(steps, yaml.SequenceNode):
            continue
        default_dir = (scalar(mapping_get(mapping_get(mapping_get(job, "defaults"), "run"), "working-directory"))
                       or workflow_dir or ".")
        censuses.append(check_job(path, scalar(job_name), root, job, steps, default_dir, problem, cache))
    return total(censuses)


def check_job(path: Path, job_id: str, root: object, job: object, steps: yaml.SequenceNode, default_dir: str,
              problem: Problem, cache: dict) -> Census:
    """Rule 8 over one job's steps, then its upload (check_upload)."""
    commands, kept_steps, scripts = 0, 0, {}
    last_step = last_pooled = None
    step_conditions, uploads = set(), []
    # Steps that queue a go test with harness-pool.sh start, and steps that wait for the pool:
    # such a go test has written all its events only once a wait after it has returned.
    waits = []
    for index, step in enumerate(steps.value, start=1):
        line = step.start_mark.line + 1
        name = scalar(mapping_get(step, "name")) or scalar(mapping_get(step, "uses")) or "a step with no name"
        where = f"{path}:{line}: step {index} of job {job_id} ({name})"
        if scalar(mapping_get(step, "uses")) == UPLOAD_ACTION:
            uploads.append((index, step))
        scan = scan_step(scalar(mapping_get(step, "run")) or "",
                         Path(scalar(mapping_get(step, "working-directory")) or default_dir), cache)
        for script in scan.scripts:
            scripts.setdefault(script, StepAt(path, line, where))
        if scan.pool_wait:
            waits.append((index, step_if(step)))
        if ENV_FILE in step_env_names(root, job, step) or scan.assigns:
            problem(path, f"{where} sets {ENV_FILE}, which only {WRITER} sets, for a script it runs: a "
                          f"step's own value sends events where the job's upload of "
                          f"$RUNNER_TEMP/go-test-events/ does not look. Take it off the step.", line=line)
        if scan.unparsable:
            problem(path, f"{where} runs {', '.join(scan.unparsable)}, so whether it runs go test is UNKNOWN: "
                          f"rule 8 reads a Python script with Python's own parser. Fix the script.", line=line)
        if scan.bare:
            problem(path, f"{where} runs {', '.join(scan.bare)} other than through {WRITER}, so it keeps no "
                          f"record of which tests it ran, passed and skipped: without -v or -json go test "
                          f"prints `ok <package> <time>` alone. Run the command as `<path to {WRITER}> go "
                          f"test ...`, or the script as `<path to {WRITER}> <script> ...`, which keeps every "
                          f"event and prints the log go test prints.", line=line)
        if scan.leaky:
            problem(path, f"{where} runs a script under {WRITER}, and the script runs {', '.join(scan.leaky)}, "
                          f"which neither runs under that writer nor tees its output into {ENV_FILE} on "
                          f"its own line, so those tests' events are kept nowhere.", line=line)
        if scan.detached:
            problem(path, f"{where} runs {', '.join(scan.detached)} detached: behind `setsid -f` with no `-w`, "
                          f"or in the background (`&`) with no `wait` of the same shell after it that runs whenever "
                          f"it does (not in a subshell, a pipeline, a function, an if or a loop of its own), "
                          f"either of which returns while the command runs, so the step can end, and the job "
                          f"upload its events, before the command has written them, and the step does not fail "
                          f"when go test does. Give setsid -w (`setsid -fw`) or take -f off, and `wait` for a "
                          f"command started with `&` in the shell that started it.", line=line)
        if scan.misspelled:
            problem(path, f"{where} runs {', '.join(scan.misspelled)} through {WRITER} with a go word other "
                          f"than `go`: the writer's first form takes `go` alone, and it runs any other word as "
                          f"a command that tees its own events, which go test does not, so the step keeps no "
                          f"event and fails. Write `go` right after the writer (`<path to {WRITER}> go test "
                          f"...`), with the go to run first on PATH.", line=line)
        if not scan.kept and not scan.bare and not scan.misspelled:
            continue
        if scan.kept:
            commands += scan.kept
            kept_steps += 1
        last_step = StepRef(index, name, line)
        if scan.pooled:
            last_pooled = StepRef(index, name, line)
        step_conditions.add(step_if(step))
        step_id = scalar(mapping_get(step, "id")) or ""
        if not step_id or step_id.startswith("__"):
            problem(path, f"{where} runs go test{'' if scan.bare else f' through {WRITER}'} and has no id: of "
                          f"its own, which names its events file (<id>.jsonl) and which a reader asks for; "
                          f"GitHub's own name for it moves when a step is added above it, and the writer "
                          f"refuses it. Give the step an id:.", line=line)
    if last_step is not None:
        check_upload(path, job_id, last_step, last_pooled, step_conditions, uploads, waits, problem)
    return Census(commands, kept_steps, int(kept_steps > 0), scripts)


def check_upload(path: Path, job_id: str, last_step: StepRef, last_pooled: StepRef | None, step_conditions: set[str],
                 uploads: list, waits: list, problem: Problem) -> None:
    """A job whose last go test step is `last_step` uploads its events after it, and after the
    pool's wait when it queues a go test in the pool (`last_pooled`)."""
    # The upload runs whenever a go test step ran: always(), or always() and the one condition
    # every such step of the job carries, and nothing else that could hold it back.
    conditions = with_shared({"always()"}, step_conditions)
    # A go test the pool runs has written all its events once a wait after its start returned.
    boundary = last_step.index
    skippable_note = ""
    if last_pooled is not None:
        # A wait the job skips waits for nothing: it counts only when it runs whenever the
        # upload does, after a failed step too, so its condition is always() or !cancelled(),
        # with or without the one condition the job's go test steps share. The upload must
        # follow the first such wait; a skippable one before it changes nothing.
        runs_after_failure = with_shared({"always()", "!cancelled()"}, step_conditions)
        guaranteed = [index for index, when in waits if index > last_pooled.index and when in runs_after_failure]
        skippable = [(index, when) for index, when in waits if index > last_pooled.index and when not in runs_after_failure]
        if not guaranteed:
            if skippable:
                at, when = skippable[0]
                problem(path, f"{path}:{last_pooled.line}: job {job_id} queues a go test with harness-pool.sh start "
                              f"(step {last_pooled.index}, {last_pooled.name}), and its wait for the pool, step {at}, "
                              f"runs only when `{when or 'success()'}` holds, so the job can skip it and upload "
                              f"before the test has written its events: give that wait `if: ${{{{ !cancelled() }}}}` "
                              f"or `if: always()`.", line=last_pooled.line)
            else:
                problem(path, f"{path}:{last_pooled.line}: job {job_id} queues a go test with harness-pool.sh start "
                              f"(step {last_pooled.index}, {last_pooled.name}) and no step after it waits for the pool "
                              f"(`harness-pool.sh wait`), so no upload can know the test has written its events.",
                        line=last_pooled.line)
            return
        boundary = max(boundary, guaranteed[0])
        before = [(index, when) for index, when in skippable if index < guaranteed[0]]
        if before:
            at, when = before[0]
            skippable_note = (f"; its wait at step {at} runs only when `{when or 'success()'}` holds, so the job "
                              f"can skip it, and only the wait at step {guaranteed[0]} counts")
    after = [step for index, step in uploads if index > boundary]
    ok = [step for step in after
          if all(scalar(mapping_get(mapping_get(step, "with"), key)) == value for key, value in UPLOAD_WITH.items())
          and step_if(step) in conditions]
    if not ok:
        wanted = ", ".join(f"{key}: {value}" for key, value in UPLOAD_WITH.items())
        problem(path, f"{path}:{last_step.line}: job {job_id} runs go test (its last such step is "
                      f"step {last_step.index}, {last_step.name}"
                      f"{f', and the pool it queues go test in is waited for at step {boundary}' if boundary != last_step.index else ''}"
                      f"{skippable_note}"
                      f") and no step after it uploads the events: add a step `uses: {UPLOAD_ACTION}` "
                      f"with `if: always()` (or `always() && ` the one condition its go test steps share) "
                      f"and `with:` {wanted}, so a reader fetches them by the job's id, a failed or "
                      f"cancelled run's among them.",
                line=last_step.line)


# The filter that starts ci.yaml's ci-filters job, the one job that runs this check on a whole
# checkout (workflow-files.yaml checks out .github alone). Every script rule 8 reads can change its
# verdict, so a change to one has to start that job: a script the filter does not select could
# gain a bare go test on a pull request this check never ran on, and the next pull request that
# starts the job would fail on a step it never touched. No file of the repository holds the
# filters: ci.yaml's changes job computes them when it runs (.github/scripts/ci-filters-generate.sh,
# from .github/ci-gates), and the ci-filters job hands this check the file it computed in
# CI_FILTERS_FILE, read as the job's dorny/paths-filter step reads it, under some-with-excludes.
# With no CI_FILTERS_FILE (workflow-files.yaml's run, a local run) the hold is UNKNOWN, and says
# so, rather than compute the filters, which takes Go, Bun and a minute.
CHECK_FILTER = "ci_filters"
# The first line of a filters file written because the filters could not be computed: every filter
# in it is '**', which selects every path and so holds nothing (ci-filters-generate.sh).
FAIL_OPEN_HEAD = "# FAIL-OPEN:"


def flat(value) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        return [pattern for item in value for pattern in flat(item)]
    return []


def hold_scripts_to_filter(reached: dict[Path, StepAt], problem: Problem) -> str:
    """Refuse each script rule 8 read (`reached`, a Census's scripts) that CHECK_FILTER does not
    select, naming the step that first reached it; the summary's phrase for the rest, UNKNOWN when
    there is no such filter to read."""
    if not reached:
        return ""
    filters = os.environ.get("CI_FILTERS_FILE", "")
    unknown = f", and whether a change to the {len(reached)} script(s) rule 8 read starts the ci-filters job UNKNOWN: "
    if not filters:
        return unknown + "no CI_FILTERS_FILE names the filters ci.yaml's changes job computed"
    try:
        text = Path(filters).read_text()
        document = yaml.safe_load(text)
    except (OSError, UnicodeDecodeError, yaml.YAMLError) as error:
        return unknown + f"cannot read CI_FILTERS_FILE's {filters}: {type(error).__name__}"
    if text.startswith(FAIL_OPEN_HEAD):
        return unknown + f"{filters} was written because the filters could not be computed"
    patterns = flat(document.get(CHECK_FILTER)) if isinstance(document, dict) else []
    if not patterns:
        return unknown + f"{filters} holds no {CHECK_FILTER} filter"
    selects = PathsFilter(patterns, "some-with-excludes")
    for script, (path, line, where) in sorted(reached.items()):
        if not selects.covers(str(script)):
            problem(path, f"{where} runs {script}, itself or through a script it runs, and rule 8 reads it, "
                          f"but the {CHECK_FILTER} filter ci.yaml's changes job computed does not select it: a "
                          f"change to that script starts no ci-filters job, the one job that runs this check, so "
                          f"a go test added to it merges unread and fails the next pull request that starts the "
                          f"job. Add a read that selects it to .github/ci-gates/ci-filters.py, the gate that "
                          f"filter is computed from.", line=line)
    return (f", and each of the {len(reached)} script(s) it read is one the {CHECK_FILTER} filter "
            f"selects")
